import random
import math

def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        # Find pivot
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate below
        pivot = A[i][i]
        for j in range(i+1, n):
            factor = A[j][i] / pivot
            for k in range(n):
                A[j][k] -= factor * A[i][k]

    return A

def rank(A):
    A = gaussian_elimination(A)
    rank = 0
    for row in A:
        if any(row):
            rank += 1
    return rank

def random_planar_cnf(n, m):
    variables = set(range(1, n+1))
    clauses = []
    for _ in range(m):
        clause = set()
        while len(clause) < 3:
            var = random.choice(list(variables))
            if random.choice([True, False]):
                clause.add(-var)
            else:
                clause.add(var)
        clauses.append(tuple(sorted(clause)))
    return clauses

def resolution_length(clauses):
    stack = []
    while True:
        new_clause = None
        for i in range(len(stack)):
            for j in range(i+1, len(stack)):
                if len(stack[i] & stack[j]) == 2:
                    new_clause = (stack[i] - stack[j]).union(stack[j] - stack[i])
                    break
            if new_clause:
                break
        if not new_clause:
            return len(stack)
        stack.append(new_clause)

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n_values = [5, 10, 15, 20, 30, 40]
    results = []

    for n in n_values:
        m = random.randint(1, min(n * (n - 1) // 2, 10))
        cnf = random_planar_cnf(n, m)
        resolution_len = resolution_length(cnf)

        hodge_rank = rank([[1 if i == j else 0 for j in range(n)] for i in range(n)])

        results.append({
            "n": n,
